package com.acme.gateway.auth;

import io.grpc.*;
import io.grpc.netty.shaded.io.grpc.netty.GrpcSslContexts;
import io.grpc.netty.shaded.io.grpc.netty.NettyChannelBuilder;
import io.grpc.stub.StreamObserver;
import javax.net.ssl.SSLSession;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

/**
 * CrossServiceAuthInterceptor handles NTLM-based authentication tokens
 * received from upstream services and validates them before forwarding
 * requests to downstream microservices.
 *
 * Security model: We receive an NTLM Type 3 message from the client,
 * validate it against our domain controller, then issue a service token
 * for downstream calls.
 */
public class CrossServiceAuthInterceptor implements ServerInterceptor {

    private static final Logger logger = Logger.getLogger(CrossServiceAuthInterceptor.class.getName());
    private static final Metadata.Key<String> AUTH_HEADER =
            Metadata.Key.of("x-ntlm-auth", Metadata.ASCII_STRING_MARSHALLER);
    private static final Metadata.Key<String> SERVICE_TOKEN_HEADER =
            Metadata.Key.of("x-service-token", Metadata.ASCII_STRING_MARSHALLER);
    private static final Metadata.Key<String> TARGET_SPN_HEADER =
            Metadata.Key.of("x-target-spn", Metadata.ASCII_STRING_MARSHALLER);

    private static final long SESSION_TIMEOUT_MS = 30000; // 30s timeout

    private final ConcurrentHashMap<String, AuthSession> activeSessions;
    private final DomainControllerClient dcClient;
    private final ServiceTokenIssuer tokenIssuer;
    private final ChannelBindingValidator channelBindingValidator;

    public CrossServiceAuthInterceptor(DomainControllerClient dcClient,
                                        ServiceTokenIssuer tokenIssuer,
                                        ChannelBindingValidator channelBindingValidator) {
        this.dcClient = dcClient;
        this.tokenIssuer = tokenIssuer;
        this.channelBindingValidator = channelBindingValidator;
        this.activeSessions = new ConcurrentHashMap<>();
    }

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call,
            Metadata headers,
            ServerCallHandler<ReqT, RespT> next) {

        String ntlmToken = headers.get(AUTH_HEADER);
        String targetSpn = headers.get(TARGET_SPN_HEADER);

        if (ntlmToken == null) {
            call.close(Status.UNAUTHENTICATED.withDescription("Missing NTLM token"), new Metadata());
            return new ServerCall.Listener<ReqT>() {};
        }

        try {
            NtlmMessage message = NtlmMessage.parse(Base64.getDecoder().decode(ntlmToken));

            if (message.getType() == NtlmMessageType.TYPE_1_NEGOTIATE) {
                return handleNegotiate(call, headers, message, next);
            } else if (message.getType() == NtlmMessageType.TYPE_3_AUTHENTICATE) {
                return handleAuthenticate(call, headers, message, targetSpn, next);
            } else {
                call.close(Status.UNAUTHENTICATED.withDescription("Invalid NTLM message type"), new Metadata());
                return new ServerCall.Listener<ReqT>() {};
            }
        } catch (Exception e) {
            logger.warning("NTLM parsing failed: " + e.getMessage());
            call.close(Status.UNAUTHENTICATED.withDescription("Token parse error"), new Metadata());
            return new ServerCall.Listener<ReqT>() {};
        }
    }

    private <ReqT, RespT> ServerCall.Listener<ReqT> handleNegotiate(
            ServerCall<ReqT, RespT> call,
            Metadata headers,
            NtlmMessage negotiate,
            ServerCallHandler<ReqT, RespT> next) {

        // Opportunistically evict expired sessions to prevent unbounded growth
        // from negotiate requests that never complete authentication.
        pruneExpiredSessions();

        // Generate challenge from DC
        byte[] challenge = dcClient.generateChallenge(negotiate.getRaw());
        String sessionId = generateSessionId();

        AuthSession session = new AuthSession(sessionId, challenge, System.currentTimeMillis());
        activeSessions.put(sessionId, session);

        // Send challenge back
        Metadata responseHeaders = new Metadata();
        responseHeaders.put(AUTH_HEADER, Base64.getEncoder().encodeToString(challenge));
        responseHeaders.put(Metadata.Key.of("x-session-id", Metadata.ASCII_STRING_MARSHALLER), sessionId);
        call.close(Status.UNAUTHENTICATED.withDescription("NTLM challenge issued"), responseHeaders);
        return new ServerCall.Listener<ReqT>() {};
    }

    private <ReqT, RespT> ServerCall.Listener<ReqT> handleAuthenticate(
            ServerCall<ReqT, RespT> call,
            Metadata headers,
            NtlmMessage authenticate,
            String targetSpn,
            ServerCallHandler<ReqT, RespT> next) {

        String sessionId = headers.get(Metadata.Key.of("x-session-id", Metadata.ASCII_STRING_MARSHALLER));
        AuthSession session = activeSessions.remove(sessionId);

        if (session == null || isSessionExpired(session)) {
            call.close(Status.UNAUTHENTICATED.withDescription("Invalid or expired session"), new Metadata());
            return new ServerCall.Listener<ReqT>() {};
        }

        // Validate the NTLM Type 3 message against the domain controller
        ValidationResult result = dcClient.validateType3(
                session.getChallenge(),
                authenticate.getRaw());

        if (!result.isValid()) {
            call.close(Status.UNAUTHENTICATED.withDescription("Authentication failed"), new Metadata());
            return new ServerCall.Listener<ReqT>() {};
        }

        // EPA (Extended Protection for Authentication) - Channel Binding check
        // This binds the NTLM auth to the TLS channel to prevent relay
        SSLSession sslSession = call.getAttributes().get(Grpc.TRANSPORT_ATTR_SSL_SESSION);
        if (sslSession != null) {
            byte[] peerCertHash = channelBindingValidator.getEndpointChannelBinding(sslSession);
            byte[] ntlmChannelBinding = authenticate.getChannelBindings();

            // REQUIRE channel bindings - reject if not present
            if (ntlmChannelBinding == null || ntlmChannelBinding.length == 0) {
                call.close(Status.UNAUTHENTICATED.withDescription("Channel binding required but not present"), new Metadata());
                return new ServerCall.Listener<ReqT>() {};
            }

            if (!channelBindingValidator.validateBinding(peerCertHash, ntlmChannelBinding)) {
                call.close(Status.UNAUTHENTICATED.withDescription("Channel binding mismatch"), new Metadata());
                return new ServerCall.Listener<ReqT>() {};
            }
        } else {
            // Reject if no TLS session - require encrypted channel
            call.close(Status.UNAUTHENTICATED.withDescription("TLS required for NTLM authentication"), new Metadata());
            return new ServerCall.Listener<ReqT>() {};
        }

        // Issue service token for downstream call
        String serviceToken = tokenIssuer.issueToken(
                result.getUsername(),
                result.getDomain(),
                targetSpn,
                session.getChallenge());

        // Attach service token to context for downstream propagation
        Context ctx = Context.current().withValue(
                Constants.SERVICE_TOKEN_CTX_KEY, serviceToken);

        return Contexts.interceptCall(ctx, call, headers, next);
    }

    private void pruneExpiredSessions() {
        long now = System.currentTimeMillis();
        for (Map.Entry<String, AuthSession> entry : activeSessions.entrySet()) {
            if ((now - entry.getValue().getCreatedAt()) > SESSION_TIMEOUT_MS) {
                activeSessions.remove(entry.getKey(), entry.getValue());
            }
        }
    }

    private boolean isSessionExpired(AuthSession session) {
        return (System.currentTimeMillis() - session.getCreatedAt()) > SESSION_TIMEOUT_MS;
    }

    private String generateSessionId() {
        byte[] random = new byte[32];
        new java.security.SecureRandom().nextBytes(random);
        return Base64.getUrlEncoder().withoutPadding().encodeToString(random);
    }
}

/**
 * ChannelBindingValidator provides EPA (Extended Protection for Authentication)
 * validation to prevent NTLM relay attacks.
 */
class ChannelBindingValidator {

    /**
     * Extracts the tls-server-end-point channel binding from the SSL session.
     */
    public byte[] getEndpointChannelBinding(SSLSession session) {
        try {
            java.security.cert.Certificate[] certs = session.getLocalCertificates();
            if (certs != null && certs.length > 0) {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                return md.digest(certs[0].getEncoded());
            }
        } catch (Exception e) {
            // Fall through
        }
        return null;
    }

    /**
     * Validates that the channel binding in the NTLM message matches
     * the actual TLS channel binding.
     */
    public boolean validateBinding(byte[] expected, byte[] fromNtlm) {
        if (expected == null || fromNtlm == null) {
            return false;
        }
        return MessageDigest.isEqual(expected, fromNtlm);
    }
}
